    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        // public watchTrades
        //
        //     {
        //         "e": "trade",       // event type
        //         "E": 1579481530912, // event time
        //         "s": "ETHBTC",      // symbol
        //         "t": 158410082,     // trade id
        //         "p": "0.01914100",  // price
        //         "q": "0.00700000",  // quantity
        //         "b": 586187049,     // buyer order id
        //         "a": 586186710,     // seller order id
        //         "T": 1579481530910, // trade time
        //         "m": false,         // is the buyer the market maker
        //         "M": true           // binance docs say it should be ignored
        //     }
        //
        //     {
        //        "e": "aggTrade",  // Event type
        //        "E": 123456789,   // Event time
        //        "s": "BNBBTC",    // Symbol
        //        "a": 12345,       // Aggregate trade ID
        //        "p": "0.001",     // Price
        //        "q": "100",       // Quantity
        //        "f": 100,         // First trade ID
        //        "l": 105,         // Last trade ID
        //        "T": 123456785,   // Trade time
        //        "m": true,        // Is the buyer the market maker?
        //        "M": true         // Ignore
        //     }
        //
        // private watchMyTrades spot
        //
        //     {
        //         "e": "executionReport",
        //         "E": 1611063861489,
        //         "s": "BNBUSDT",
        //         "c": "m4M6AD5MF3b1ERe65l4SPq",
        //         "S": "BUY",
        //         "o": "MARKET",
        //         "f": "GTC",
        //         "q": "2.00000000",
        //         "p": "0.00000000",
        //         "P": "0.00000000",
        //         "F": "0.00000000",
        //         "g": -1,
        //         "C": '',
        //         "x": "TRADE",
        //         "X": "PARTIALLY_FILLED",
        //         "r": "NONE",
        //         "i": 1296882607,
        //         "l": "0.33200000",
        //         "z": "0.33200000",
        //         "L": "46.86600000",
        //         "n": "0.00033200",
        //         "N": "BNB",
        //         "T": 1611063861488,
        //         "t": 109747654,
        //         "I": 2696953381,
        //         "w": false,
        //         "m": false,
        //         "M": true,
        //         "O": 1611063861488,
        //         "Z": "15.55951200",
        //         "Y": "15.55951200",
        //         "Q": "0.00000000"
        //     }
        //
        // private watchMyTrades future/delivery
        //
        //     {
        //         "s": "BTCUSDT",
        //         "c": "pb2jD6ZQHpfzSdUac8VqMK",
        //         "S": "SELL",
        //         "o": "MARKET",
        //         "f": "GTC",
        //         "q": "0.001",
        //         "p": "0",
        //         "ap": "33468.46000",
        //         "sp": "0",
        //         "x": "TRADE",
        //         "X": "FILLED",
        //         "i": 13351197194,
        //         "l": "0.001",
        //         "z": "0.001",
        //         "L": "33468.46",
        //         "n": "0.00027086",
        //         "N": "BNB",
        //         "T": 1612095165362,
        //         "t": 458032604,
        //         "b": "0",
        //         "a": "0",
        //         "m": false,
        //         "R": false,
        //         "wt": "CONTRACT_PRICE",
        //         "ot": "MARKET",
        //         "ps": "BOTH",
        //         "cp": false,
        //         "rp": "0.00335000",
        //         "pP": false,
        //         "si": 0,
        //         "ss": 0
        //     }
        //
        string? executionType = this.safeString(trade, "x");
        bool isTradeExecution = (executionType == "TRADE");
        if (!isTradeExecution)
        {
            return this.parseTrade(trade, market);
        }
        string? id = this.safeString2(trade, "t", "a");
        Int64? timestamp = this.safeInteger(trade, "T");
        string? price = this.safeString2(trade, "L", "p");
        string? amount = this.safeString(trade, "q");
        if (isTradeExecution)
        {
            amount = this.safeString(trade, "l", amount);
        }
        string? cost = this.safeString(trade, "Y");
        if ((cost == null))
        {
            if (((price != null)) && ((amount != null)))
            {
                cost = Precise.stringMul(price, amount);
            }
        }
        string? marketId = this.safeString(trade, "s");
        string fallbackType = "spot";
        if ((trade != null && ((IDictionary<string, object>)trade).ContainsKey("ps")))
        {
            fallbackType = "contract";
        }
        object marketType = fallbackType;
        if ((market != null))
        {
            marketType = getValue(market, "type");
        }
        string? symbol = this.safeSymbol(marketId, market, null, marketType);
        string? side = this.safeStringLower(trade, "S");
        string? takerOrMaker = null;
        string? orderId = this.safeString(trade, "i");
        if ((trade != null && ((IDictionary<string, object>)trade).ContainsKey("m")))
        {
            if ((side == null))
            {
                side = ((this.safeBool(trade, "m") == true)) ? "sell" : "buy"; // this is reversed intentionally
            }
            takerOrMaker = ((this.safeBool(trade, "m") == true)) ? "maker" : "taker";
        }
        Dictionary<string, object> fee = null;
        string? feeCost = this.safeString(trade, "n");
        if ((feeCost != null))
        {
            string? feeCurrencyId = this.safeString(trade, "N");
            string? feeCurrencyCode = this.safeCurrencyCode(feeCurrencyId);
            fee = new Dictionary<string, object>() {
                { "cost", feeCost },
                { "currency", feeCurrencyCode },
            };
        }
        string? type = this.safeStringLower(trade, "o");
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "id", id },
            { "order", orderId },
            { "type", type },
            { "takerOrMaker", takerOrMaker },
            { "side", side },
            { "price", price },
            { "amount", amount },
            { "cost", cost },
            { "fee", fee },
        });
    }

    public virtual void handleTrade(WebSocketClient client, object message)
    {
        // the trade streams push raw trade information in real-time
        // each trade has a unique buyer and seller
        string? marketId = this.safeString(message, "s");
        // resolve the market from the transport url — an ambiguous id like
        // BTCUSDT maps to both the spot and the linear swap market
        bool isSpot = this.isSpotUrl(client);
        string marketType = "contract";
        if (isSpot)
        {
            marketType = "spot";
        }
        Dictionary<string, object> market = this.safeMarket(marketId, null, null, marketType);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        string messageHash = ("trade::" + symbol);
        Dictionary<string, object> trade = this.parseWsTrade(message, market);
        ccxt.pro.ArrayCache tradesArray = ((ccxt.pro.ArrayCache)this.safeValue(this.trades, symbol));
        if ((tradesArray == null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            tradesArray = new ArrayCache(limit);
        }
        tradesArray.append(trade);
        this.trades[(string)symbol] = tradesArray;
        client.resolve(tradesArray, messageHash);
    }

